/* the mask's own rasterisation; the record's size decides the drawn size. */
#define SC_LABEL_WIDTH 116u
#define SC_LABEL_HEIGHT 16u

/* the caption's four variants: dim and white ink on black and blue ground.
   the stock table holds all four; which sits at which id does not matter,
   because each record is measured before it is painted. */
#define SC_CAPTION_FIRST_ID 0x1449u
#define SC_CAPTION_COUNT 4u

/* the select grid's three tiles, dim, normal and selected. */
#define SC_TILE_FIRST_ID 0x15aau
#define SC_TILE_COUNT 3u

/* Painted by the core while it builds the image tables, from each record's
   own size, ground and ink. Nothing is measured here and nothing is guessed:
   a module cannot read a stock record while it starts, because the player has
   not built its table yet, which is why the paint happens on the core side. */
static void sc_labels_install(void)
{
    unsigned index;
    unsigned made = 0;
    if (!framework->images || !framework->images->replace_masked) {
        framework->log_line("sidechain: the caption needs the image service");
        return;
    }
    for (index = 0; index < SC_CAPTION_COUNT; index++)
        made += (unsigned)framework->images->replace_masked(
            &sc_owner, SC_CAPTION_FIRST_ID + index,
            SC_LABEL_WIDTH, SC_LABEL_HEIGHT, sc_label_caption_coverage);
    for (index = 0; index < SC_TILE_COUNT; index++)
        made += (unsigned)framework->images->replace_masked(
            &sc_owner, SC_TILE_FIRST_ID + index,
            SC_LABEL_WIDTH, SC_LABEL_HEIGHT, sc_label_caption_coverage);
    framework->log_number("sidechain: labels relabelled = ", made);
}

/* The painted pixels belong to the table once it publishes; this only takes
   the registrations out. */
static void sc_labels_release(void)
{
    if (framework->images && framework->images->release_native)
        framework->images->release_native(&sc_owner);
}

